-- NABUUMA base schema
create extension if not exists pgcrypto;
do $$ begin create type member_role as enum ('owner','manager','trainer','staff'); exception when duplicate_object then null; end $$;
do $$ begin create type recipe_status as enum ('draft','published','archived'); exception when duplicate_object then null; end $$;
do $$ begin create type inventory_movement_type as enum ('opening','purchase','consumption','waste','adjustment'); exception when duplicate_object then null; end $$;
do $$ begin create type qc_result as enum ('pass','remake'); exception when duplicate_object then null; end $$;
create table if not exists businesses(id uuid primary key default gen_random_uuid(),name text not null,currency text not null default 'AED',timezone text not null default 'Asia/Dubai',created_at timestamptz not null default now());
create table if not exists business_members(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role member_role not null default 'staff',created_at timestamptz not null default now(),unique(business_id,user_id));
create table if not exists products(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,code text not null,name text not null,description text,active_recipe_version_id uuid,created_at timestamptz not null default now(),unique(business_id,code));
create table if not exists ingredients(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,name text not null,base_unit text not null check(base_unit in ('g','kg','ml','l','each')),density_g_ml numeric,created_at timestamptz not null default now(),unique(business_id,name));
create table if not exists suppliers(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,name text not null,created_at timestamptz not null default now());
create table if not exists ingredient_prices(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,ingredient_id uuid not null references ingredients(id) on delete cascade,supplier_id uuid references suppliers(id),purchase_quantity numeric not null check(purchase_quantity>0),purchase_price numeric not null check(purchase_price>=0),usable_yield_fraction numeric not null default 1 check(usable_yield_fraction>0 and usable_yield_fraction<=1),effective_from timestamptz not null default now());
create table if not exists recipe_versions(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,product_id uuid not null references products(id) on delete cascade,version_number int not null,status recipe_status not null default 'draft',method text not null default '',glassware text,ice_spec text,garnish text,notes text,published_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(product_id,version_number));
create table if not exists recipe_ingredients(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,recipe_version_id uuid not null references recipe_versions(id) on delete cascade,ingredient_id uuid not null references ingredients(id),quantity numeric not null check(quantity>0),unit text not null,sort_order int not null default 0);
alter table products drop constraint if exists products_active_recipe_fk; alter table products add constraint products_active_recipe_fk foreign key(active_recipe_version_id) references recipe_versions(id) deferrable initially deferred;
create table if not exists inventory_movements(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,ingredient_id uuid not null references ingredients(id),movement_type inventory_movement_type not null,quantity numeric not null,unit text not null,unit_cost numeric,reference_type text,reference_id uuid,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists staff_profiles(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,user_id uuid references auth.users(id),display_name text not null,role member_role not null default 'staff',active boolean not null default true,created_at timestamptz not null default now());
create table if not exists courses(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,code text not null,name text not null,pass_threshold numeric not null default 75,created_at timestamptz not null default now(),unique(business_id,code));
create table if not exists training_assignments(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,staff_id uuid not null references staff_profiles(id) on delete cascade,course_id uuid not null references courses(id),status text not null default 'assigned',assigned_at timestamptz not null default now());
create table if not exists assessments(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,staff_id uuid not null references staff_profiles(id),course_id uuid not null references courses(id),score numeric not null check(score>=0 and score<=100),passed boolean not null,assessed_at timestamptz not null default now(),assessed_by uuid references auth.users(id));
create table if not exists certifications(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,staff_id uuid not null references staff_profiles(id),course_id uuid not null references courses(id),certificate_id text not null unique,issued_at timestamptz not null default now(),expires_at timestamptz);
create table if not exists qc_checks(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,product_id uuid not null references products(id),recipe_version_id uuid references recipe_versions(id),staff_id uuid references staff_profiles(id),recipe_accuracy boolean not null,visual_standard boolean not null,balance boolean not null,hygiene boolean not null,result qc_result not null,notes text,created_at timestamptz not null default now());
create table if not exists service_events(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,product_id uuid not null references products(id),recipe_version_id uuid references recipe_versions(id),staff_id uuid references staff_profiles(id),served_at timestamptz not null default now(),quantity int not null default 1,remake boolean not null default false);
create table if not exists waste_records(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,ingredient_id uuid references ingredients(id),quantity numeric,cost numeric,unit text,reason text,created_at timestamptz not null default now(),created_by uuid references auth.users(id));
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,user_id uuid references auth.users(id),action text not null,entity_type text,entity_id uuid,metadata jsonb,created_at timestamptz not null default now());
create table if not exists subscriptions(id uuid primary key default gen_random_uuid(),business_id uuid unique not null references businesses(id) on delete cascade,plan_code text not null default 'pilot',status text not null default 'trialing',billing_customer_id text,billing_subscription_id text,current_period_end timestamptz,created_at timestamptz not null default now());
create index if not exists idx_members_user on business_members(user_id); create index if not exists idx_products_business on products(business_id); create index if not exists idx_recipe_product on recipe_versions(product_id); create index if not exists idx_inventory_business_ingredient on inventory_movements(business_id,ingredient_id); create index if not exists idx_qc_business_created on qc_checks(business_id,created_at desc);
create or replace function public.is_member(target_business uuid) returns boolean language sql security definer stable set search_path=public as $$ select exists(select 1 from business_members where business_id=target_business and user_id=auth.uid()); $$;
create or replace function public.has_role(target_business uuid, allowed member_role[]) returns boolean language sql security definer stable set search_path=public as $$ select exists(select 1 from business_members where business_id=target_business and user_id=auth.uid() and role=any(allowed)); $$;
create or replace function public.create_business(business_name text,currency_code text default 'AED',timezone_name text default 'Asia/Dubai') returns jsonb language plpgsql security definer set search_path=public as $$ declare b businesses; m business_members; u uuid:=auth.uid(); begin if u is null then raise exception 'Authentication required'; end if; if exists(select 1 from business_members where user_id=u) then select bm.* into m from business_members bm where bm.user_id=u order by created_at limit 1; return jsonb_build_object('business_id',m.business_id,'role',m.role); end if; insert into businesses(name,currency,timezone) values(business_name,currency_code,timezone_name) returning * into b; insert into business_members(business_id,user_id,role) values(b.id,u,'owner') returning * into m; insert into subscriptions(business_id,plan_code,status) values(b.id,'pilot','trialing'); return jsonb_build_object('business_id',b.id,'role',m.role,'business',jsonb_build_object('id',b.id,'name',b.name,'currency',b.currency,'timezone',b.timezone)); end $$;
grant execute on function public.create_business(text,text,text) to authenticated;
do $$ declare t text; p record; begin foreach t in array array['businesses','business_members','products','ingredients','suppliers','ingredient_prices','recipe_versions','recipe_ingredients','inventory_movements','staff_profiles','courses','training_assignments','assessments','certifications','qc_checks','service_events','waste_records','audit_logs','subscriptions'] loop execute format('alter table %I enable row level security',t); for p in select policyname from pg_policies where schemaname='public' and tablename=t loop execute format('drop policy if exists %I on %I',p.policyname,t); end loop; end loop; end $$;
create policy businesses_select on businesses for select using (is_member(id)); create policy members_select on business_members for select using (is_member(business_id)); create policy members_manage on business_members for all using (has_role(business_id,ARRAY['owner','manager']::member_role[])) with check (has_role(business_id,ARRAY['owner','manager']::member_role[]));
do $$ declare t text; begin foreach t in array array['products','ingredients','suppliers','ingredient_prices','recipe_versions','recipe_ingredients','inventory_movements','staff_profiles','courses','training_assignments','assessments','certifications','qc_checks','service_events','waste_records','audit_logs','subscriptions'] loop execute format('create policy %I_select on %I for select using (is_member(business_id))',t,t); end loop; end $$;
create policy products_write on products for all using(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])); create policy ingredients_write on ingredients for all using(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])); create policy suppliers_write on suppliers for all using(has_role(business_id,ARRAY['owner','manager']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager']::member_role[])); create policy prices_write on ingredient_prices for all using(has_role(business_id,ARRAY['owner','manager']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager']::member_role[])); create policy recipes_write on recipe_versions for all using(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])); create policy recipe_ingredients_write on recipe_ingredients for all using(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])); create policy inventory_write on inventory_movements for insert with check(has_role(business_id,ARRAY['owner','manager','staff']::member_role[])); create policy inventory_update on inventory_movements for update using(has_role(business_id,ARRAY['owner','manager']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager']::member_role[])); create policy staff_write on staff_profiles for all using(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])); create policy training_write on training_assignments for all using(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])); create policy assessment_write on assessments for insert with check(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])); create policy cert_write on certifications for insert with check(has_role(business_id,ARRAY['owner','manager','trainer']::member_role[])); create policy qc_write on qc_checks for insert with check(is_member(business_id)); create policy service_write on service_events for insert with check(is_member(business_id)); create policy waste_write on waste_records for insert with check(is_member(business_id)); create policy audit_write on audit_logs for insert with check(is_member(business_id)); create policy subs_write on subscriptions for update using(has_role(business_id,ARRAY['owner','manager']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager']::member_role[]));
create or replace function prevent_published_recipe_change() returns trigger language plpgsql as $$ begin if old.status='published' then raise exception 'Published recipe versions are immutable'; end if; return new; end; $$; drop trigger if exists recipe_immutable on recipe_versions; create trigger recipe_immutable before update or delete on recipe_versions for each row execute function prevent_published_recipe_change();
create or replace function publish_recipe(p_recipe uuid) returns void language plpgsql security definer set search_path=public as $$ declare r recipe_versions; begin select * into r from recipe_versions where id=p_recipe; if not has_role(r.business_id,ARRAY['owner','manager','trainer']::member_role[]) then raise exception 'Not permitted'; end if; update recipe_versions set status='archived' where product_id=r.product_id and status='published' and id<>r.id; update recipe_versions set status='published',published_at=now() where id=r.id; update products set active_recipe_version_id=r.id where id=r.product_id; end $$; grant execute on function public.publish_recipe(uuid) to authenticated;
create or replace view recipe_costs as select rv.id recipe_version_id,rv.business_id,rv.product_id,coalesce(sum(ri.quantity*(ip.purchase_price/ip.purchase_quantity)/ip.usable_yield_fraction),0)::numeric as ingredient_cost from recipe_versions rv left join recipe_ingredients ri on ri.recipe_version_id=rv.id left join lateral(select * from ingredient_prices x where x.ingredient_id=ri.ingredient_id and x.business_id=rv.business_id order by effective_from desc limit 1) ip on true group by rv.id,rv.business_id,rv.product_id;